import React from 'react';

function Footer() {
  return (
    <footer className="app-footer">
      <p>
        Experiment: RESTful API design, validation, global exception handling &amp; correlation-ID
        based request tracing.
      </p>
      <p className="credit">
        Developed by <strong>Anurag</strong> · Spring Boot + React
      </p>
    </footer>
  );
}

export default Footer;
